insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Liora Vennt','#e06fb8',2515,3567,'Primeira noite no Boteco do Mag e Malorne','Cheguei a Amox com uma moeda no bolso e saí do boteco com três. Aqui ninguém paga pela música: pagam para eu cantar a versão “certa” da sessão do parlamento. Aprendi rápido que em Amox a verdade é a que ganha mais aplausos.',array['https://cdn-ugc.kanka.io/campaigns/382414/a14f4e47-fc59-4274-bfdd-005e808410a0.jpg']::text[],'2026-10-04 19:30-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Liora Vennt','#e06fb8',2365,3717,'Apostei no parlamento (e perdi)','Apostei que o parlamentar das alcunhas engraçadas ia votar contra a taxa das tavernas. Votou a favor, sob vaias. Perdi a aposta, mas ganhei uma canção. Silêncio demais aqui é fraqueza — anotei para não esquecer.','{}'::text[],'2026-10-09 21:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Liora Vennt','#e06fb8',2792,3920,'Valantir não grita','Depois de Amox, o silêncio de Valantir dói nos ouvidos. Todo mundo é educado e ninguém diz nada. Fui ao Banco dos Nove Cofres só para ver por dentro: guardas que não piscam e um mármore que dá vontade de cochichar.',array['https://cdn-ugc.kanka.io/campaigns/382414/01a012b7-133d-710f-8dd1-b1f664f8d415.png']::text[],'2026-10-18 10:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Liora Vennt','#e06fb8',2845,4655,'Porto Murado: aqui a lei é simples','Ninguém pergunta de que lado você está. Pergunta só se você pagou o cais. Gostei. Consegui passagem num barco de pescadores para o leste, rumo a Costa Funda, em troca de três noites tocando no convés.',array['https://cdn-ugc.kanka.io/campaigns/382414/a1614a6f-4e2f-4340-be1b-67b7047b4e45.webp']::text[],'2026-11-02 16:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Liora Vennt','#e06fb8',2943,5372,'Costa Funda','Uma ilha pequena, gente desconfiada e muito peixe. Os pescadores contam histórias estranhas sobre o mar a nordeste, o tal Bico da Gaivota. Quero voltar com mais calma (e com alguém que saiba nadar).','{}'::text[],'2026-11-14 08:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Brana Forjafunda','#e89a3c',1563,1759,'Saindo de Bradória Profunda','Trinta anos martelando nas forjas de baixo. Hoje subi a escadaria toda de uma vez e o ar da superfície ainda queima o nariz. Levo o martelo do meu avô e uma lista de encomendas do Conselho de Artesãos.',array['https://cdn-ugc.kanka.io/campaigns/382414/a150481b-df50-436e-955c-1df559d35b03.png']::text[],'2026-10-02 07:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Brana Forjafunda','#e89a3c',1816,2181,'Lake City cresceu','Até pouco tempo era só um punhado de casas perto do lago. Agora tem gente nova chegando todo dia. Consertei a dobradiça do templo para o Irmão Theodric e ele me deu um chá horrível e uma bênção boa.',array['https://cdn-ugc.kanka.io/campaigns/382414/a1fd726c-fa59-4e0c-9bd4-158a6817cc3f.webp','https://cdn-ugc.kanka.io/campaigns/382414/a1fd7362-19dd-4147-85e8-94d8a1e99234.webp']::text[],'2026-10-11 15:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Brana Forjafunda','#e89a3c',1010,1370,'Skjoldheim, atrás das paredes de gelo','O frio do Desfiladeiro não perdoa. Achei Skjoldheim por causa da fumaça das chaminés. Gente de poucas palavras, bom aço. Fiquei três dias trocando técnicas de têmpera. Ouvi falar de uma dragonesa branca e decidi que não quero conhecê-la.',array['https://cdn-ugc.kanka.io/campaigns/382414/a190c4f9-7ab7-424f-bb7a-22d14a7b4d0f.webp']::text[],'2026-10-27 12:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Brana Forjafunda','#e89a3c',1534,5378,'Dolrath constrói o que o inverno não quebra','Atravessei o norte inteiro para chegar aqui. O lema da cidade é quase o meu. Mas todo mundo fala baixo sobre o ataque dos vampiros, e as portas fecham cedo. Vou ficar e ajudar a reforçar os portões.','{}'::text[],'2026-11-20 18:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Tico Pé-Ligeiro','#4fc3c9',2800,3700,'Undermine','“Quem não sobe na malandragem… desce no caixão.” Repeti isso a noite toda para não esquecer onde eu estava. Ganhei um mapa de túneis num jogo de cartas. Tenho quase certeza de que o mapa é falso. Quase.',array['https://cdn-ugc.kanka.io/campaigns/382414/a165136c-b415-4039-897e-2fea78c141c2.png']::text[],'2026-10-06 23:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Tico Pé-Ligeiro','#4fc3c9',2197,5021,'A cidade das aranhas','Arthrolatt é rural, tranquila… e cheia de teias do tamanho de um celeiro. Os fazendeiros nem ligam. Eu ligo. Dormi de botas.',array['https://cdn-ugc.kanka.io/campaigns/382414/a1c3b26a-6dfe-4ba4-90dd-38ef3cbac6a4.webp']::text[],'2026-10-16 05:30-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Tico Pé-Ligeiro','#4fc3c9',2860,2560,'Na borda da Floresta sem Retorno','Parei onde as árvores começam a ficar escuras demais. Um caçador me disse que quem entra procurando atalho vira atalho para outra coisa. Contornei pelo norte. Duas vezes.','{}'::text[],'2026-10-30 17:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
insert into public.galtherdara_notas(personagem,cor,y,x,titulo,texto,imagens,criado,dono) values ('Tico Pé-Ligeiro','#4fc3c9',2280,2240,'Bloompog é… estranha','Uma cidade normal de humanos, dizem. Normal demais. As flores me seguiram com os olhos (as flores!). Alguém falou de um portal ao sul. Vou perguntar mais amanhã, de dia, longe das flores.',array['https://cdn-ugc.kanka.io/campaigns/382414/a16152f3-ca45-4ec5-9b21-d05f13ecf90c.webp']::text[],'2026-11-12 13:00-03',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'));
